{"path":"/home/roko/Documents/Projects/myactuator/firmware/esp32/include/types.h","content":"#pragma once

#include <stdint.h>
#include <stdbool.h>

// Motor status
typedef enum {
    MOTOR_STATUS_IDLE = 0,
    MOTOR_STATUS_ENABLED,
    MOTOR_STATUS_RUNNING,
    MOTOR_STATUS_FAULT,
    MOTOR_STATUS_DISABLED
} MotorStatus;

// Protocol types
typedef enum {
    PROTO_CAN = 0,
    PROTO_RS485,
    PROTO_ETHERCAT,
    PROTO_COUNT
} ProtocolType;

// Frame types
typedef enum {
    FRAME_TYPE_STATUS_REPORT = 0x01,
    FRAME_TYPE_POSITION_CMD = 0x02,
    FRAME_TYPE_VELOCITY_CMD = 0x03,
    FRAME_TYPE_TORQUE_CMD = 0x04,
    FRAME_TYPE_PARAM_READ = 0x05,
    FRAME_TYPE_PARAM_WRITE = 0x06,
    FRAME_TYPE_FIRMWARE_UPDATE = 0x08
} FrameType;

// Unified frame structure (64 bytes)
typedef struct {
    uint8_t type;
    uint8_t motorId;
    uint8_t data[62];
} Frame;

// Motor configuration
typedef struct {
    uint8_t motorId;
    uint8_t motorSeries;
    ProtocolType protocol;
    uint16_t encoderBits;
    uint8_t powerClass;
    uint8_t gearboxType;
    bool hasBrake;
    uint8_t driveType;
    uint8_t communication;
    float maxVelocity;
    float maxTorque;
    float kp;
    float ki;
    float kd;
    float maxPosition;
    uint32_t canBusSpeed;
    uint32_t rs485BaudRate;
    uint8_t encoderPinA;
    uint8_t encoderPinB;
    uint8_t encoderPinZ;
    uint8_t motorPinPWM;
    uint8_t motorPinDir;
} MotorConfig;

// Motor status report
typedef struct {
    int32_t position;
    float velocity;
    float current;
    float temperature;
    bool enabled;
    uint8_t errorCode;
} MotorStatusReport;

// Logger levels
typedef enum {
    LOG_ERROR = 0,
    LOG_WARN,
    LOG_INFO,
    LOG_DEBUG
} LogLevel;
